            [ exact (okpar_par P1 psi1 A ga Hu)
            | intros x Hx;
              apply (okpar_par ((x,psi0)::P1) psi1 (open_tm_wrt_tm B (a_Var_f x))
                               (gb x (@notin_union_1 x L (dom P1) Hx)));
